  if (pwm_counter < pwm_period * duty_cycle) begin
    pwm_out <= 1;
  end else begin
    pwm_out <= 0;
  end

  pwm_counter <= pwm_counter + 1;
  if (pwm_counter >= pwm_period) begin
    pwm_counter <= 0;
  end
end

endmodule
