    )(
        input                   ce,
        input                   rst,
        input                   clk,
        input  [WIDTH - 1:0]    in,
        output [WIDTH - 1:0]    out
    );

    reg [WIDTH - 1:0] state;

    always @(posedge clk) begin
        if (rst) begin
            state <= 0;
        end
        else if (ce) begin
            state <= in;
        end
    end

    assign out = state;

endmodule
