    input [2:0] op,
    output reg [3:0] out,
    output reg valid
);

reg [3:0] mux_out;
reg [3:0] alu_out;

// 16-to-1 multiplexer
always @(*) begin
    case(sel)
        4'd0: mux_out = in[3:0];
        4'd1: mux_out = in[7:4];
        4'd2: mux_out = in[11:8];
        4'd3: mux_out = in[15:12];
        default: mux_out = 4'b0;
    endcase
end

