    case(op)
        3'b000: alu_out = A + B;
        3'b001: alu_out = A - B;
        3'b010: alu_out = A & B;
        3'b011: alu_out = A | B;
        3'b100: alu_out = A ^ B;
        default: alu_out = 4'b0;
    endcase
end

