module edge_detector (
    input clk,
    input [7:0] in,
    output reg out
);

    reg [7:0] prev_in;

    always @(posedge clk) begin
        if (in != prev_in) begin
            out <= 1;
        end else begin
            out <= 0;
        end
        prev_in <= in;
    end

endmodule
module or_gate (
    input wire in1,
    input wire in2,
    output reg out
);

    always @(*) begin
        out = in1 | in2;
    end

endmodule
