module decoder_2to4 (
    input clk,
    input enable,
    output reg [1:0] out
);

    always @(posedge clk) begin
        if (enable) begin
            out <= 2'b00;
        end else begin
            case (out)
                2'b00: out <= 2'b01;
                2'b01: out <= 2'b10;
                2'b10: out <= 2'b11;
                2'b11: out <= 2'b00;
            endcase
        end
    end

