    input clk,
    input reset,
    input enable,
    output reg [3:0] out
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            if (enable) begin
                out <= out + 1;
            end
        end
    end

endmodule

