    input clk,
    input reset,
    input select,
    input [3:0] counter_in,
    output reg [3:0] out
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            if (select) begin
                out <= counter_in + select;
            end
        end
    end

endmodule
